CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 REAL, c1 REAL, c2 ANY COLLATE NOCASE, c3 INTEGER DEFAULT 'd', c4 TEXT NOT NULL DEFAULT 0) STRICT;
INSERT INTO t0(c0, c1, c2, c3, c4) VALUES(-19.873, 34.792, x'595758ae', 724, '日本');
INSERT INTO t0(c0, c1, c2, c3, c4) VALUES(30.361, x'01d1', NULL, -187, 'gamma');
