CREATE TABLE t1(id INTEGER PRIMARY KEY, c0  DEFAULT 'd', c1 INT COLLATE NOCASE, c2 NUMERIC, c3 BLOB, c4 BLOB COLLATE NOCASE, ref INTEGER REFERENCES t0(id));
INSERT INTO t1(c0, c1, c2, c3, c4, ref) VALUES(x'4cadf7006b', -908.945, 'pi', NULL, x'', 1);
