SELECT id, c1, NOT c2 FROM t1 ORDER BY id, c0 DESC, c1, c2, c3 DESC, c4 DESC, ref DESC;
SELECT x'7e38d687de', abs(coalesce(abs('epsilon'), coalesce('rho', 4.5e-310)));
SELECT id, c4 IN (id, x'813b', 4), CASE WHEN CAST(c0 AS TEXT) THEN CAST(ref AS INTEGER) IS NULL ELSE NULL END FROM t1 ORDER BY id, c0, c1 DESC, c2 DESC, c3, c4 DESC, ref DESC;
SELECT CASE WHEN abs(CASE WHEN x'70dce7a2cb' THEN 2 ELSE -643 END) THEN -(-49.115) ELSE typeof(NULL IN (159, 'phi', NULL)) END, -(CASE WHEN -881.990 THEN 'phi' ELSE -2 END IN (coalesce(-400, -3), NULL, NULL));
SELECT id, CAST(typeof(CAST(id AS NUMERIC)) AS BLOB), (c2 / coalesce(c4 IS NULL, id)) FROM t0 ORDER BY id, c0, c1, c2 DESC, c3, c4;
SELECT 'MU', x'09';
SELECT id, 521 BETWEEN c0 AND id, CASE WHEN c2 THEN -506 ELSE CASE WHEN NOT c1 THEN '日本' ELSE iif(c2, '0x1F', 'rho') END END FROM t1 ORDER BY id, c0 DESC, c1, c2, c3, c4, ref DESC;
SELECT NULL, 9223372036854775807;
SELECT id, x'23', nullif((NULL || CAST(c4 AS BLOB)), NULL BETWEEN ref AND c4) FROM t1 ORDER BY id, c0, c1, c2 DESC, c3, c4, ref DESC;
SELECT 'gamma', NULL;
SELECT id, CAST(CAST(c0 AS BLOB) AS INTEGER), id FROM t0 ORDER BY id, c0 DESC, c1, c2, c3, c4 DESC;
SELECT abs(((NULL >> -0.0) >= -228.93 IN (65.0768, 'upsilon', NULL))), iif('MU', -(CASE WHEN 'pi' THEN NULL ELSE NULL END), NULL);
SELECT id, c2 IS NULL, nullif(nullif('über', id), CASE WHEN c0 THEN id ELSE NULL END IS NULL) FROM t0 ORDER BY id, c0, c1, c2, c3, c4;
SELECT CASE WHEN NOT NOT '日本' THEN typeof(NULL BETWEEN 3.141592653589793 AND NULL) ELSE x'680025' END, 'zeta';
